package hotel.documents;

import hotel.reservations.Reservation;
import hotel.rooms.Room;

/** Factory for creating the appropriate document type based on the reservation. */
public final class DocumentFactory {

    private DocumentFactory() {}

    /** Returns a document object (ReservationReceipt, CompanyInvoice, or InternationalBookingReceipt). */
    public static Object createDocument(Reservation reservation, Room room) {
        if (reservation.guest().companyCnpj() != null) {
            return new CompanyInvoice(reservation, room);
        } else if (reservation.guest().guestPassport() != null) {
            return new InternationalBookingReceipt(reservation, room);
        } else {
            return new ReservationReceipt(reservation, room);
        }
    }

    public static String getText(Object document) {
        if (document instanceof ReservationReceipt receipt) {
            return receipt.text();
        } else if (document instanceof CompanyInvoice invoice) {
            return invoice.text();
        } else if (document instanceof InternationalBookingReceipt receipt) {
            return receipt.text();
        }
        throw new IllegalArgumentException("Unknown document type: " + document.getClass());
    }
}

