                || isBlank(body.guestName())
                || isBlank(body.guestEmail())
                || body.checkIn() == null
                || body.checkOut() == null
                || body.guests() == null
                || body.ratePlan() == null) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
        }

        // Validate identification: must be one of CPF, CNPJ+companyName, or passport+country
        boolean hasCpf = !isBlank(body.guestCpf());
        boolean hasCompany = !isBlank(body.companyCnpj()) || !isBlank(body.companyName());
        boolean hasPassport = !isBlank(body.guestPassport()) || !isBlank(body.guestCountry());

        int identificationMethods = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
        if (identificationMethods != 1) {
            throw new HotelException(
                    ErrorCode.INVALID_REQUEST,
                    "reservation must have exactly one identification: guestCpf, or companyCnpj+companyName, or guestPassport+guestCountry");
        }

        // Validate each method has all required fields
        if (hasCpf && (hasCompany || hasPassport)) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "cannot mix identification methods");
