            throw new HotelException(
                    ErrorCode.INVALID_REQUEST, "international identification requires both guestPassport and guestCountry");
        }

        Guest guest = new Guest(
                body.guestName(),
                body.guestEmail(),
                body.guestCpf(),
                body.companyCnpj(),
                body.companyName(),
                body.guestPassport(),
                body.guestCountry());
