            return YearMonth.parse(month);
        } catch (DateTimeParseException badMonth) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
        }
    }

    private static String requiredQueryParam(Context ctx, String name) {
        String value = ctx.queryParam(name);
        if (value == null) {
            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
        }
        return value;
    }

    private static boolean isBlank(String text) {
        return text == null || text.isBlank();
    }

    private static Document documentToJson(Object documentObj) {
        if (documentObj instanceof ReservationReceipt receipt) {
            return Document.from(receipt);
        } else if (documentObj instanceof CompanyInvoice invoice) {
            return Document.from(invoice);
        } else if (documentObj instanceof InternationalBookingReceipt receipt) {
            return Document.from(receipt);
        }
        throw new IllegalArgumentException("Unknown document type: " + documentObj.getClass());
    }
}

